function validate([stations, r, k]) {
  const n = stations.length;
  if (n < 1 || n > 100000) return 'stations needs 1 to 10^5 cities.';
  if (stations.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each stations[i] is an integer from 0 to 10^5.';
  if (!Number.isInteger(r) || r < 0 || r > n - 1) return 'r is between 0 and n - 1.';
  if (!Number.isInteger(k) || k < 0 || k > 1000000000) return 'k is between 0 and 10^9.';
  return null;
}

