function maxPower(stations, r, k) {
  const n = stations.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + stations[i];
  }
  const power = new Array(n);
  for (let i = 0; i < n; i++) {
    power[i] = prefix[Math.min(n, i + r + 1)] - prefix[Math.max(0, i - r)];
  }

  const canReach = (target) => {
    const diff = new Array(n + 1).fill(0);
    let extra = 0;
    let budget = k;
    for (let i = 0; i < n; i++) {
      extra += diff[i];
      const need = target - power[i] - extra;
      if (need <= 0) continue;
      if (need > budget) return false;
      budget -= need;
      extra += need;
      diff[Math.min(n, i + 2 * r + 1)] -= need;
    }
    return true;
  };

  let low = Math.min(...power);
  let high = low + k;
  while (low < high) {
    const mid = low + Math.ceil((high - low) / 2);
    if (canReach(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

