function maxPower(stations, r, k) {
  // Try every way to share the k new stations among the cities.
  const n = stations.length;
  const built = stations.slice();
  let best = -1;
  const weakest = () => {
    let least = Infinity;
    for (let j = 0; j < n; j++) {
      let total = 0;
      for (let i = 0; i < n; i++) if (Math.abs(i - j) <= r) total += built[i];
      least = Math.min(least, total);
    }
    return least;
  };
  const place = (city, left) => {
    if (city === n - 1) {
      built[city] += left;
      best = Math.max(best, weakest());
      built[city] -= left;
      return;
    }
    for (let add = 0; add <= left; add++) {
      built[city] += add;
      place(city + 1, left - add);
      built[city] -= add;
    }
  };
  place(0, k);
  return best;
}

