function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 6);
    const top = rand() < 0.5 ? 3 : 9;
    const stations = Array.from({ length: n }, () => (rand() < 0.3 ? 0 : pick(0, top)));
    return [stations, pick(0, n - 1), pick(0, 5)];
  }
  const n = 2000;
  const sparse = rand() < 0.5;
  const stations = Array.from({ length: n }, () => (sparse && rand() < 0.8 ? 0 : pick(0, 100000)));
  const r = rand() < 0.5 ? pick(0, 20) : pick(0, n - 1);
  const k = rand() < 0.5 ? pick(0, 1000) : pick(0, 1000000000);
  return [stations, r, k];
}
